public with sharing class OpportunityTriggerHandler {
  public static void handleBeforeUpdate(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {
    for (Opportunity opp : newList) {
      Opportunity oldOpp = oldMap.get(opp.Id);
      if (opp.StageName == 'Negotiation' && oldOpp.Amount != null && opp.Amount != null) {
        Decimal dropPct = (oldOpp.Amount - opp.Amount) / oldOpp.Amount;
        if (dropPct > 0.5) {
          opp.addError('Amount cannot drop more than 50% once in Negotiation.');
        }
      }
    }
  }
}

public class AccountEnrichmentQueueable implements Queueable {
  private List<Id> accountIds;

  public AccountEnrichmentQueueable(List<Id> accountIds) {
    this.accountIds = accountIds;
  }

  public void execute(QueueableContext context) {
    List<Account> accounts = [SELECT Id, Industry, AnnualRevenue FROM Account WHERE Id IN :accountIds];
    for (Account acc : accounts) {
      if (acc.Industry == null) {
        acc.Industry = 'Unknown';
      }
    }
    update accounts;

    if (!Test.isRunningTest()) {
      System.enqueueJob(new SendEnrichmentSummaryQueueable(accountIds));
    }
  }
}

public class SendEnrichmentSummaryQueueable implements Queueable {
  private List<Id> accountIds;

  public SendEnrichmentSummaryQueueable(List<Id> accountIds) {
    this.accountIds = accountIds;
  }

  public void execute(QueueableContext context) {
    Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
    email.setToAddresses(new String[] { UserInfo.getUserEmail() });
    email.setSubject('Account Enrichment Complete');
    email.setPlainTextBody('Enrichment finished for ' + accountIds.size() + ' accounts.');
    Messaging.sendEmail(new Messaging.SingleEmailMessage[] { email });
  }
}

public class DeactivateInactiveAccountContactsBatch implements Database.Batchable<sObject> {

  public Database.QueryLocator start(Database.BatchableContext bc) {
    return Database.getQueryLocator([
      SELECT Id, IsActive__c
      FROM Contact
      WHERE Account.Status__c = 'Inactive' AND IsActive__c = true
    ]);
  }

  public void execute(Database.BatchableContext bc, List<Contact> scope) {
    for (Contact c : scope) {
      c.IsActive__c = false;
    }
    update scope;
  }

  public void finish(Database.BatchableContext bc) {
    System.debug('Inactive-account contact deactivation batch complete.');
  }
}

