public class AccountRollupQueueable implements Queueable {
  private List<Id> remainingAccountIds;
  private static final Integer CHUNK_SIZE = 200;

  public AccountRollupQueueable(List<Id> accountIds) {
    this.remainingAccountIds = accountIds;
  }

  public void execute(QueueableContext context) {
    Integer size = Math.min(CHUNK_SIZE, remainingAccountIds.size());
    List<Id> currentChunk = new List<Id>();
    for (Integer i = 0; i < size; i++) {
      currentChunk.add(remainingAccountIds.remove(0));
    }

    Map<Id, Decimal> totalsByAccountId = new Map<Id, Decimal>();
    for (AggregateResult ar : [
      SELECT AccountId acctId, SUM(Amount) total
      FROM Opportunity
      WHERE AccountId IN :currentChunk AND IsClosed = false
      GROUP BY AccountId
    ]) {
      totalsByAccountId.put((Id) ar.get('acctId'), (Decimal) ar.get('total'));
    }

    List<Account> toUpdate = new List<Account>();
    for (Id acctId : currentChunk) {
      toUpdate.add(new Account(Id = acctId, Open_Pipeline__c = totalsByAccountId.get(acctId)));
    }
    update toUpdate;

    if (!remainingAccountIds.isEmpty() && !Test.isRunningTest()) {
      System.enqueueJob(new AccountRollupQueueable(remainingAccountIds));
    }
  }
}

